export const DB_VERSION = 5;
const M = "media/";
const SOURCE = "איור מקורי שנוצר בקוד עבור הדמו (Beautigo)";

export const video = (name: string): MediaItem =>
  isReelId(name) ? reelMedia(name) : { type: "video", src: `${M}${name}.mp4`, srcWebm: `${M}${name}.webm`, poster: `${M}${name}.jpg`, source: SOURCE };
/** Business cover/avatar: a reel's poster frame, or a generated illustration. */
const art = (name: string) => (isReelId(name) ? reelPoster(name) : `${M}${name}.jpg`);
export const image = (file: string): MediaItem => ({ type: "image", src: `${M}${file}.jpg`, source: SOURCE });

