const week = (start: number, end: number, days = [0, 1, 2, 3, 4]): WorkingRange[] => days.map((weekday) => ({ weekday, start: start * 60, end: end * 60 }));
const friday = (start: number, end: number): WorkingRange[] => [{ weekday: 5, start: start * 60, end: end * 60 }];
const lunch = (h = 13, m = 0, days = [0, 1, 2, 3, 4]): WorkingRange[] => days.map((weekday) => ({ weekday, start: h * 60 + m, end: h * 60 + m + 30 }));

