const PRIVACY = { privateSaves: false, showFollowing: true, allowMessagesFromBusinesses: true };

function user(id: string, name: string, username: string, role: User["role"], extra: Partial<User> = {}): User {
  return {
    id,
    name,
    username,
    role,
    interests: [],
    followingBusinesses: [],
    followingPros: [],
    blockedUserIds: [],
    blockedBusinessIds: [],
    status: "active",
    isDemo: true,
    createdAt: "2026-01-01T09:00:00.000Z",
    privacy: { ...PRIVACY },
    ...extra,
  };
}

export const DEMO_ACCOUNTS = {
  customer: "u-dana",
  owner: "u-owner-nova",
  staff: "u-staff-noa",
  admin: "u-admin",
};

export function createSeed(nowDate = new Date()): DB {
  const now = DateTime.fromJSDate(nowDate).setZone(TZ);
  const iso = (d: DateTime) => d.toUTC().toISO()!;
  const db: DB = {
    version: DB_VERSION,
    cities: CITIES.map((c) => ({ ...c })),
    users: [
      user("u-dana", "דנה כהן", "dana.cohen", "customer", { cityId: "tlv", interests: ["hair", "nails", "blowdry"], email: "dana@demo.beautigo", phone: "050-0000001" }),
      user("u-yoav", "יואב לוי", "yoav.levi", "customer", { cityId: "rg", interests: ["barber"] }),
      user("u-michal", "מיכל אברהם", "michal.a", "customer", { cityId: "jlm", interests: ["makeup", "brows"] }),
      user("u-neta", "נטע ברק", "neta.b", "customer", { cityId: "tlv", interests: ["nails"] }),
      user("u-ron", "רון אשכנזי", "ron.a", "customer", { cityId: "hfa", interests: ["barber"] }),
      user("u-shira", "שירה פרידמן", "shira.f", "customer", { cityId: "hrz", interests: ["blowdry", "makeup"] }),
      user("u-admin", "צוות Beautigo", "beautigo.team", "admin"),
    ],
    businesses: [],
    professionals: [],
    services: [],
    posts: [],
    stories: [],
    comments: [],
    collections: [],
    appointments: [],
    blockedTimes: [],
    reviews: [],
    conversations: [],
    notifications: [],
    reports: [],
    campaigns: [],
    payments: [],
    audit: [],
    integrationEvents: [],
    analytics: [],
  };

  for (const d of BIZ) {
    db.users.push(user(d.owner.id, d.owner.name, d.username + ".owner", "business", { businessId: d.id, cityId: d.cityId }));
    const biz: Business = {
      id: d.id,
      name: d.name,
      username: d.username,
      description: d.description,
      categories: d.categories,
      cityId: d.cityId,
      address: d.address,
      serviceAreaCityIds: d.serviceAreas ?? [],
      isMobile: !!d.mobile,
      cover: art(d.cover),
      avatar: art(d.avatar),
      ownerId: d.owner.id,
      status: d.status ?? "active",
      isDemo: true,
      phone: "03-0000000",
      openingHours: [...week(9, 19), ...friday(8, 14)],
      policy: {
        cancelHours: 24,
        requestExpiryHours: 24,
        paymentHoldMinutes: 15,
        text: "ביטול או שינוי ללא עלות עד 24 שעות לפני התור. ביטול מאוחר — מקדמה (אם שולמה) לא מוחזרת.",
      },
      pinnedPostIds: [],
      quickReplies: ["תודה! נתראה בתור 😊", "אפשר לשלוח תמונת השראה?", "יש לנו מקום פנוי מחר בבוקר", "המחיר הסופי ייקבע בייעוץ קצר בסטודיו"],
      calendar: { status: "disconnected" },
      createdAt: "2026-02-01T09:00:00.000Z",
    };
    db.businesses.push(biz);

    const services: Service[] = d.services.map((s, i) => ({
      id: `${d.id}-s${i}`,
      businessId: d.id,
      description: "",
      bufferMin: 0,
      priceFrom: false,
      approval: "auto",
      payment: "at_business",
      deposit: { type: "fixed", value: 0 },
      active: true,
      ...s,
    }));
    db.services.push(...services);

    d.pros.forEach((p, i) => {
      const pro: Professional = {
        id: `${d.id}-p${i}`,
        businessId: d.id,
        name: p.name,
        title: p.title,
        specialties: p.specialties,
        avatar: "",
        serviceIds: p.services.map((x) => services[x].id),
        workingHours: p.hours ?? [...week(9, 19), ...friday(8, 14)],
        breaks: lunch(13, i % 2 ? 30 : 0),
        active: true,
      };
      db.professionals.push(pro);
      if (p.staffLogin) db.users.push(user(p.staffLogin, p.name, d.username + "." + i, "staff", { businessId: d.id, professionalId: pro.id }));
    });

    d.posts.forEach((p, i) => {
      const media = p.kind === "reel" ? [video(p.media[0])] : p.media.map(image);
      const published = now.minus({ hours: p.daysAgo * 24 });
      const post: Post = {
        id: `${d.id}-post${i}`,
        businessId: d.id,
        kind: p.kind,
        media,
        cover: media[0].poster ?? media[0].src,
        caption: p.caption,
        subtitle: p.subtitle,
        tags: p.tags,
        cityId: p.city ?? d.cityId,
        serviceId: p.svc != null ? services[p.svc].id : undefined,
        professionalId: p.pro != null ? `${d.id}-p${p.pro}` : undefined,
        status: "published",
        likedBy: [],
        savedCount: p.saves ?? 0,
        views: p.views ?? 0,
        shares: Math.round((p.likes ?? 0) / 12),
        createdAt: iso(published),
        publishedAt: iso(published),
        isSample: true,
      };
      // demo like counts: represented by placeholder ids so totals are visible
      post.likedBy = Array.from({ length: p.likes ?? 0 }, (_, k) => `demo-liker-${k}`);
      db.posts.push(post);
    });
  }

  const B = (id: string) => db.businesses.find((b) => b.id === id)!;
  B("b-nova").pinnedPostIds = ["b-nova-post0"];
  B("b-nova").calendar = { status: "connected", accountEmail: "nova.studio@demo.example", calendarId: "nova-main", calendarName: "יומן סטודיו נובה", lastSyncAt: iso(now.minus({ minutes: 12 })) };
  B("b-gloss").calendar = { status: "error", accountEmail: "gloss@demo.example", calendarId: "gloss", calendarName: "תורים — גלוס בר", lastSyncAt: iso(now.minus({ days: 2 })), lastError: "ההרשאה פגה (invalid_grant). יש להתחבר מחדש." };
  db.integrationEvents.push({ id: "ie1", businessId: "b-gloss", integration: "google_calendar", level: "error", message: "סנכרון נכשל: invalid_grant — נדרש חיבור מחדש (דמו)", createdAt: iso(now.minus({ days: 2 })), resolved: false });

  // Social graph
  const dana = db.users.find((u) => u.id === "u-dana")!;
  dana.followingBusinesses = ["b-nova", "b-atelier", "b-gloss"];
  dana.followingPros = ["b-chrome-p0"];
  db.users.find((u) => u.id === "u-yoav")!.followingBusinesses = ["b-blade"];
  const like = (postId: string, uid: string) => db.posts.find((p) => p.id === postId)!.likedBy.push(uid);
  like("b-nova-post0", "u-dana");
  like("b-atelier-post0", "u-dana");
  db.collections.push(
    { id: "col-1", userId: "u-dana", name: "השראה לחתונה", postIds: ["b-nova-post0", "b-libi-post0", "b-gloss-post0"], createdAt: iso(now.minus({ days: 6 })) },
    { id: "col-2", userId: "u-dana", name: "ציפורניים לקיץ", postIds: ["b-atelier-post0", "b-chrome-post0"], createdAt: iso(now.minus({ days: 3 })) },
  );
  db.comments.push(
    { id: "c1", postId: "b-nova-post0", userId: "u-neta", text: "המעבר מושלם! כמה זמן זה מחזיק?", createdAt: iso(now.minus({ hours: 5 })), hidden: false },
    { id: "c2", postId: "b-nova-post0", userId: "u-owner-nova", text: "תודה נטע! בערך 3–4 חודשים עם טיפוח נכון", createdAt: iso(now.minus({ hours: 4 })), hidden: false },
    { id: "c3", postId: "b-atelier-post0", userId: "u-shira", text: "איזה גוון זה בדיוק?", createdAt: iso(now.minus({ hours: 2 })), hidden: false },
    { id: "c4", postId: "b-blade-post0", userId: "u-ron", text: "קישור לאתר זול יותר >>> spam.example", createdAt: iso(now.minus({ hours: 9 })), hidden: false },
    { id: "c5", postId: "b-nova-post0", userId: "u-dana", text: "@nova.studio אפשר כזה גם על שיער קצר? #בלייאז׳", createdAt: iso(now.minus({ hours: 3 })), hidden: false, likedBy: ["u-neta", "u-shira"] },
    { id: "c6", postId: "b-nova-post0", userId: "u-owner-nova", text: "@dana.cohen בטח! על קצר זה יוצא עוד יותר רך", createdAt: iso(now.minus({ hours: 2 })), hidden: false, parentId: "c5", likedBy: ["u-dana"] },
    { id: "c7", postId: "b-atelier-post0", userId: "u-owner-atelier", text: "@shira.f זה נוד חלבי 103 של הסטודיו 💅", createdAt: iso(now.minus({ hours: 1 })), hidden: false, parentId: "c3" },
    { id: "c8", postId: "b-chrome-post0", userId: "u-neta", text: "הכרום הזה 😍 שומרת לחתונה", createdAt: iso(now.minus({ hours: 7 })), hidden: false, likedBy: ["u-dana", "u-michal", "u-shira"] },
  );
  db.comments.find((c) => c.id === "c2")!.likedBy = ["u-neta", "u-dana"];
  db.comments.find((c) => c.id === "c1")!.likedBy = ["u-dana"];

  // Appointments placed into real free slots so the demo calendar is valid
  const book = (o: {
    biz: string;
    svc: number;
    pro?: number;
    dayOffset: number;
    pick: number;
    customerId?: string;
    guestName?: string;
    status: Appointment["status"];
    source?: string;
    inspo?: string[];
    note?: string;
  }) => {
    const business = B(o.biz);
    const service = db.services.find((s) => s.id === `${o.biz}-s${o.svc}`)!;
    const proId = o.pro != null ? `${o.biz}-p${o.pro}` : null;
    // Past appointments: search slots as if "now" were a week earlier
    const ref = o.dayOffset < 0 ? now.plus({ days: o.dayOffset - 1 }).toJSDate() : nowDate;
    for (let k = 0; k < 7; k++) {
      const date = now.plus({ days: o.dayOffset + k }).toISODate()!;
      const slots = getSlots(db, { businessId: business.id, serviceId: service.id, date, professionalId: proId }, ref);
      const slot = slots[Math.min(o.pick, slots.length - 1)];
      if (!slot) continue;
      const start = new Date(slot.start);
      const a: Appointment = {
        id: `apt-${db.appointments.length + 1}`,
        businessId: business.id,
        customerId: o.customerId,
        guestName: o.guestName,
        professionalId: proId ?? slot.professionalIds[0],
        serviceId: service.id,
        snapshot: snapshotOf(service, business),
        start: start.toISOString(),
        end: new Date(start.getTime() + service.durationMin * 60_000).toISOString(),
        status: o.status,
        holdExpiresAt:
          o.status === "pending_approval" ? iso(now.plus({ hours: 20 })) : o.status === "pending_payment" ? iso(now.plus({ minutes: 14 })) : undefined,
        sourcePostId: o.source,
        inspirationPostIds: o.inspo ?? [],
        note: o.note,
        payment: { status: "none", amount: 0 },
        history: [{ at: iso(now.minus({ days: 2 })), by: o.customerId ?? business.ownerId, action: o.customerId ? "created" : "created_manual" }],
        createdAt: iso(o.dayOffset < 0 ? now.plus({ days: o.dayOffset - 3 }) : now.minus({ days: 2 })),
        createdBy: o.customerId ? "customer" : "business",
      };
      if (o.status === "confirmed" && service.payment === "deposit") a.payment = { status: "paid_demo", amount: a.snapshot.deposit };
      db.appointments.push(a);
      return a;
    }
    throw new Error("seed: no slot for " + o.biz);
  };

  // Dana: upcoming confirmed from a reel, pending approval, pending payment, completed (reviewable), completed+reviewed, cancelled
  const a1 = book({ biz: "b-nova", svc: 0, pro: 0, dayOffset: 2, pick: 3, customerId: "u-dana", status: "confirmed", source: "b-nova-post1", inspo: ["b-nova-post1"], note: "רוצה לשמור על האורך" });
  const a2 = book({ biz: "b-libi", svc: 1, dayOffset: 9, pick: 1, customerId: "u-dana", status: "pending_approval", source: "b-libi-post0", inspo: ["b-libi-post0", "b-nova-post0"], note: "חתונה בגן אירועים, צריך להגיע עד 16:00" });
  book({ biz: "b-atelier", svc: 2, pro: 0, dayOffset: 4, pick: 2, customerId: "u-dana", status: "pending_payment", source: "b-atelier-post0", inspo: ["b-atelier-post0"] });
  const past1 = book({ biz: "b-blade", svc: 0, pro: 1, dayOffset: -6, pick: 2, customerId: "u-dana", status: "completed" });
  const past2 = book({ biz: "b-gloss", svc: 1, pro: 1, dayOffset: -12, pick: 1, customerId: "u-dana", status: "completed", source: "b-gloss-post0" });
  book({ biz: "b-skin", svc: 0, dayOffset: -3, pick: 4, customerId: "u-dana", status: "cancelled" }).cancelReason = "ביטלתי בגלל מילואים של בן הזוג";
  void past1;

  // Other customers — fill Nova's calendar for today and this week
  book({ biz: "b-nova", svc: 1, pro: 2, dayOffset: 0, pick: 1, customerId: "u-neta", status: "confirmed" });
  book({ biz: "b-nova", svc: 2, pro: 1, dayOffset: 0, pick: 2, customerId: "u-shira", status: "confirmed" });
  book({ biz: "b-nova", svc: 0, pro: 0, dayOffset: 1, pick: 0, guestName: "רותם (טלפון)", status: "confirmed" });
  book({ biz: "b-nova", svc: 3, pro: 0, dayOffset: 5, pick: 0, customerId: "u-michal", status: "pending_approval", source: "b-nova-post0", inspo: ["b-nova-post0"], note: "רוצה דבש כמו בסרטון" });
  book({ biz: "b-nova", svc: 1, pro: 2, dayOffset: 3, pick: 5, customerId: "u-yoav", status: "confirmed" });
  book({ biz: "b-nova", svc: 0, pro: 2, dayOffset: -2, pick: 2, customerId: "u-neta", status: "no_show" });
  book({ biz: "b-nova", svc: 1, pro: 0, dayOffset: -4, pick: 1, customerId: "u-shira", status: "completed" });
  book({ biz: "b-nova", svc: 3, pro: 1, dayOffset: 6, pick: 1, customerId: "u-yoav", status: "rejected" }).cancelReason = "אין מספיק זמן למורכבות הזו ביום הזה";
  book({ biz: "b-blade", svc: 1, pro: 0, dayOffset: 1, pick: 2, customerId: "u-yoav", status: "confirmed", source: "b-blade-post0" });
  book({ biz: "b-blade", svc: 1, pro: 0, dayOffset: -9, pick: 1, customerId: "u-ron", status: "completed" });
  book({ biz: "b-atelier", svc: 0, pro: 1, dayOffset: -8, pick: 3, customerId: "u-neta", status: "completed" });
  book({ biz: "b-kav", svc: 0, dayOffset: -5, pick: 2, customerId: "u-michal", status: "completed" });

  // Reviews exist only for completed appointments (marked as sample)
  const review = (aptId: string, rating: number, text: string, reply?: string) => {
    const a = db.appointments.find((x) => x.id === aptId)!;
    db.reviews.push({
      id: `rv-${db.reviews.length + 1}`,
      appointmentId: a.id,
      businessId: a.businessId,
      professionalId: a.professionalId,
      customerId: a.customerId!,
      rating,
      text,
      reply: reply ? { text: reply, at: iso(now.minus({ days: 1 })) } : undefined,
      hidden: false,
      createdAt: iso(DateTime.fromISO(a.end).plus({ days: 1 })),
      isSample: true,
    });
  };
  review(past2.id, 5, "גלים בדיוק כמו בסרטון. החזיק עד הערב!", "תודה דנה! מחכות לך שוב");
  const completed = db.appointments.filter((a) => a.status === "completed" && a.id !== past1.id && a.id !== past2.id);
  review(completed[0].id, 4, "מקצועית ונעימה, קצת המתנה בכניסה.");
  review(completed[1].id, 5, "הפייד הכי נקי שעשו לי.", "תודה רון!");
  review(completed[2].id, 5, "הג׳ל מחזיק כבר שלושה שבועות בלי שבר.");
  review(completed[3].id, 3, "איפור יפה אבל התחיל באיחור של 20 דקות.");

  // Messages
  db.conversations.push(
    {
      id: "cv1",
      customerId: "u-dana",
      businessId: "b-nova",
      appointmentId: a1.id,
      createdAt: iso(now.minus({ days: 2 })),
      lastReadAt: { "u-dana": iso(now.minus({ hours: 3 })) },
      messages: [
        { id: "m1", senderId: "u-dana", text: "היי! אפשר משהו בסגנון הזה? רוצה לשמור על האורך", attachmentPostId: "b-nova-post1", createdAt: iso(now.minus({ days: 2 })) },
        { id: "m2", senderId: "u-owner-nova", text: "בטח! זה יתאים לך מאוד. נתאים את השכבות לצורת הפנים. נתראה בתור 😊", createdAt: iso(now.minus({ hours: 2 })) },
      ],
    },
    {
      id: "cv2",
      customerId: "u-dana",
      businessId: "b-libi",
      appointmentId: a2.id,
      createdAt: iso(now.minus({ days: 1 })),
      lastReadAt: { "u-dana": iso(now), "u-owner-libi": iso(now.minus({ days: 1 })) },
      messages: [{ id: "m3", senderId: "u-dana", text: "שלחתי בקשה לאיפור כלה, אשמח לאישור 🙏", createdAt: iso(now.minus({ days: 1 })) }],
    },
    {
      id: "cv3",
      customerId: "u-yoav",
      businessId: "b-nova",
      createdAt: iso(now.minus({ hours: 6 })),
      lastReadAt: {},
      messages: [{ id: "m4", senderId: "u-yoav", text: "יש לכם תור לפן מחר בערב?", createdAt: iso(now.minus({ hours: 6 })) }],
    },
  );

  // Notifications
  const n = (userId: string, category: "appointments" | "messages" | "social" | "business", title: string, body: string, link: string, hoursAgo: number, read = false) =>
    db.notifications.push({ id: `n${db.notifications.length + 1}`, userId, category, title, body, link, createdAt: iso(now.minus({ hours: hoursAgo })), read });
  n("u-dana", "messages", "הודעה חדשה מסטודיו נובה", "בטח! זה יתאים לך מאוד…", "/messages/cv1", 2);
  n("u-dana", "appointments", "תזכורת: מחר בסטודיו נובה", "תספורת נשים", `/appointments/${a1.id}`, 5, true);
  n("u-dana", "social", "אטלייה לק פרסמו רילס חדש", "נוד חלבי לשגרה", "/post/b-atelier-post0", 7);
  n("u-owner-nova", "appointments", "בקשת תור חדשה", "מיכל אברהם מבקשת בלייאז׳", "/manage/appointments", 3);
  n("u-owner-nova", "messages", "הודעה חדשה", "יואב לוי: יש לכם תור לפן מחר בערב?", "/messages/cv3", 6);

  // Reports
  db.reports.push(
    { id: "rp1", reporterId: "u-neta", targetType: "comment", targetId: "c4", reason: "ספאם", details: "קישור פרסומי", status: "open", createdAt: iso(now.minus({ hours: 8 })) },
    { id: "rp2", reporterId: "u-ron", targetType: "post", targetId: "b-rishon-post0", reason: "שימוש בתמונה ללא רשות", details: "דיווח לדוגמה לבדיקת תור הדיווחים", status: "open", createdAt: iso(now.minus({ hours: 20 })) },
    { id: "rp3", reporterId: "u-michal", targetType: "review", targetId: "rv-5", reason: "תוכן פוגעני", details: "", status: "dismissed", resolution: "הביקורת עניינית — לא הוסרה", resolvedBy: "u-admin", createdAt: iso(now.minus({ days: 3 })) },
  );

  // Campaigns (simulated promotion — no real billing)
  db.campaigns.push(
    { id: "cmp1", businessId: "b-nova", postId: "b-nova-post0", cityIds: ["tlv", "rg"], budget: 500, start: iso(now.minus({ days: 3 })), end: iso(now.plus({ days: 11 })), status: "active", metrics: { impressions: 8420, clicks: 312, bookings: 9 }, createdAt: iso(now.minus({ days: 3 })) },
    { id: "cmp2", businessId: "b-gloss", postId: "b-gloss-post1", cityIds: ["hrz"], budget: 250, start: iso(now.minus({ days: 10 })), end: iso(now.plus({ days: 4 })), status: "paused", metrics: { impressions: 2100, clicks: 74, bookings: 2 }, createdAt: iso(now.minus({ days: 10 })) },
  );

  // Simulated payment records
  for (const a of db.appointments.filter((x) => x.payment.status === "paid_demo")) {
    db.payments.push({ id: `pay-${a.id}`, appointmentId: a.id, businessId: a.businessId, customerId: a.customerId ?? "", amount: a.payment.amount, status: "succeeded_demo", createdAt: a.createdAt });
  }
  db.payments.push({ id: "pay-failed-1", appointmentId: db.appointments[2].id, businessId: "b-atelier", customerId: "u-dana", amount: 50, status: "failed_demo", createdAt: iso(now.minus({ minutes: 3 })) });

  db.audit.push({ id: "au1", actorId: "u-admin", action: "approve_business", targetType: "business", targetId: "b-rishon", reason: "פרטי העסק נבדקו", createdAt: iso(now.minus({ days: 20 })) });

  // Analytics history (demo numbers)
  for (const p of db.posts) {
    for (let k = 0; k < Math.min(40, Math.round(p.views / 150)); k++) db.analytics.push({ id: `ev-${p.id}-${k}`, type: "view", businessId: p.businessId, postId: p.id, at: iso(now.minus({ hours: k * 5 })) });
    for (let k = 0; k < Math.round(p.views / 900); k++) db.analytics.push({ id: `bs-${p.id}-${k}`, type: "booking_start", businessId: p.businessId, postId: p.id, at: iso(now.minus({ hours: k * 13 })) });
  }
  for (const b of db.businesses) for (let k = 0; k < 18; k++) db.analytics.push({ id: `pv-${b.id}-${k}`, type: "profile_visit", businessId: b.id, at: iso(now.minus({ hours: k * 9 })) });

  // Stories (24h) — sample content, made from the same original illustrations
  const storyOf = (id: string, biz: string, file: string, hoursAgo: number, extra: Partial<Story> = {}) => {
    const created = now.minus({ hours: hoursAgo });
    const isVideo = !file.startsWith("square-") && !file.startsWith("cover-");
    db.stories.push({
      id,
      businessId: biz,
      media: isVideo ? { ...video(file), overlays: extra.media?.overlays } : { ...image(file), overlays: extra.media?.overlays },
      createdAt: iso(created),
      expiresAt: iso(created.plus({ hours: 24 })),
      viewers: [],
      likedBy: [],
      isSample: true,
      ...extra,
      ...(extra.media ? { media: { ...(isVideo ? video(file) : image(file)), ...extra.media } } : {}),
    });
  };
  const ov = (text: string, y = 70, style: "plain" | "box" | "outline" = "box") => [{ id: `ov-${text.length}-${y}`, text, x: 50, y, style, color: "#ffffff" }];
  storyOf("st-nova-1", "b-nova", "DB9RyR9Rmp4", 2, { serviceId: "b-nova-s3", media: { ...video("DB9RyR9Rmp4"), overlays: ov("נשארו 2 מקומות לבלייאז׳ השבוע") } });
  storyOf("st-nova-2", "b-nova", "DGV680QRjhK", 1, { media: { ...video("DGV680QRjhK"), overlays: ov("מאחורי הקלעים ✂️", 18, "outline") } });
  storyOf("st-blade-1", "b-blade", "DUJcoDpjlp4", 5, { serviceId: "b-blade-s1", media: { ...video("DUJcoDpjlp4"), overlays: ov("הכיסא פנוי היום מ־17:00") } });
  storyOf("st-atelier-1", "b-atelier", "DI9NDWvxJJp", 3, { sharedPostId: "b-atelier-post0" });
  storyOf("st-chrome-1", "b-chrome", "DF_OXQtT6-3", 8, { media: { ...video("DF_OXQtT6-3"), overlays: ov("כרום פנינה — הטרנד של הסתיו") } });
  storyOf("st-libi-1", "b-libi", "Dd4RGV-K2ht", 4, { serviceId: "b-libi-s0", media: { ...video("Dd4RGV-K2ht"), overlays: ov("פנוי למחר בערב 💄") } });
  storyOf("st-gloss-1", "b-gloss", "DIcZCKixkYK", 11);
  storyOf("st-carmel-1", "b-carmel", "C2iNxGBsbe0", 6, { serviceId: "b-carmel-s1", media: { ...video("C2iNxGBsbe0"), overlays: ov("תורים לילדים גם ביום שישי") } });
  storyOf("st-old", "b-kav", "DL-TXS5xZjW", 30); // already expired — never shown
  const fans = ["u-dana", "u-neta", "u-shira", "u-michal", "u-yoav", "u-ron"];
  for (const st of db.stories) {
    st.viewers = fans.slice(0, 2 + (st.id.length % 4)).map((userId, k) => ({ userId, at: iso(now.minus({ minutes: 20 + k * 37 })) }));
    st.likedBy = fans.slice(0, st.id.length % 3);
  }
  // Watch-time history for creator insights (demo numbers)
  const sources: TrafficSource[] = ["feed", "feed", "feed", "following", "discover", "profile", "share", "nearby", "tag", "story"];
  let seedN = 11;
  const rnd = () => ((seedN = (seedN * 9301 + 49297) % 233280) / 233280);
  for (const p of db.posts.filter((x) => x.kind === "reel")) {
    const len = Math.min(30, Math.max(6, (p.media[0].src.startsWith("reels/") ? REELS[p.media[0].src.slice(6, -4)]?.seconds : 0) || 7));
    const quality = 0.45 + (p.likedBy.length % 7) / 14; // some reels hold attention better
    for (let k = 0; k < Math.min(60, Math.round(p.views / 90)); k++) {
      const watched = Math.min(len * 2, Math.max(0.6, len * quality * (0.3 + rnd() * 1.6)));
      db.analytics.push({ id: `w-${p.id}-${k}`, type: "watch", businessId: p.businessId, postId: p.id, seconds: Math.round(watched * 10) / 10, completed: watched >= len * 0.95, source: sources[Math.floor(rnd() * sources.length)], at: iso(now.minus({ hours: k * 3 + rnd() * 3 })) });
    }
  }
  for (const b of db.businesses) for (let k = 0; k < 9; k++) db.analytics.push({ id: `fl-${b.id}-${k}`, type: "follow", businessId: b.id, at: iso(now.minus({ days: k * 3 + 1 })) });

  return db;
}
